// Builds dist/worker.js: the page, its stylesheet and its script embedded in the Worker.
// No dependencies.  Run:  node build.mjs
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';

const read = (path) => readFileSync(new URL(path, import.meta.url), 'utf8');

const assets = {
  html: read('./site/index.html'),
  css: read('./site/protocol.css'),
  js: read('./site/protocol.js'),
};

mkdirSync(new URL('./dist/', import.meta.url), { recursive: true });

writeFileSync(
  new URL('./dist/worker.js', import.meta.url),
  '// Generated by build.mjs. Edit site/ and worker/src/, not this file.\n' +
    'const ASSETS = ' + JSON.stringify(assets) + ';\n\n' +
    read('./worker/src/index.js')
);

// A single self-contained file for looking at the page without a server.
// Opened from disk it runs against a local stand-in for the registry.
const inline = assets.html
  .replace('<link rel="stylesheet" href="protocol.css">', () => '<style>' + assets.css + '</style>')
  .replace('<script src="protocol.js" defer></script>', () => '<script>window.ML_LOCAL=true;' + assets.js.replace(/<\/script/gi, '<\\/script') + '</script>');
writeFileSync(new URL('./dist/preview.html', import.meta.url), inline);

console.log('built dist/worker.js and dist/preview.html');
